async function* readArchive(chunks) {
  const iterator = chunks[Symbol.asyncIterator]();
  let eof = false;
  let failed = false;

  try {
    const decoder = new TextDecoder("utf-8", { ignoreBOM: true });
    let chunk = null;
    let offset = 0;
    let line = 1;
    let parts = [];

    while (true) {
      let complete = false;

      while (!complete && !eof) {
        if (chunk === null || offset === chunk.length) {
          const result = await iterator.next();

          if (result.done) {
            eof = true;
            const tail = decoder.decode();
            if (tail.length) parts.push(tail);
            break;
          }

          chunk = result.value;
          offset = 0;
          continue;
        }

        const newline = chunk.indexOf(10, offset);
        const end = newline === -1 ? chunk.length : newline;
        const text = decoder.decode(chunk.subarray(offset, end), {
          stream: true
        });

        if (text.length) parts.push(text);

        if (newline === -1) {
          offset = end;
        } else {
          offset = newline + 1;
          complete = true;
        }
      }

      const record = parts.join("");
      parts = [];
      const recordLine = line++;

      if (record.trim().length !== 0) {
        let value;

        try {
          value = JSON.parse(record);
        } catch (cause) {
          const error = new SyntaxError(
            `Invalid JSON record at line ${recordLine}`
          );
          error.code = "INVALID_RECORD";
          error.line = recordLine;
          error.cause = cause;
          throw error;
        }

        yield value;
      }

      if (eof) return;
    }
  } catch (error) {
    failed = true;
    throw error;
  } finally {
    if (!eof) {
      try {
        const close = iterator.return;
        if (typeof close === "function") {
          await close.call(iterator);
        }
      } catch (error) {
        if (!failed) throw error;
      }
    }
  }
}
